import { Sprite, Texture } from 'pixi.js';

import { Slide } from '../base-slide';

export class ImageSlide extends Slide {
    private screenImage: Sprite;

    constructor(imageTexture: Texture) {
        super();

        this.screenImage = new Sprite(imageTexture);
        this.screenImage.anchor.set(0.5);
        this.addChild(this.screenImage);
    }

    public resize(width: number, height: number, offset: { x: number, y: number }): void {
        super.resize(width, height, offset);

        const widthScale = width / this.screenImage.texture.width;
        const heightScale = height / this.screenImage.texture.height;
        const scale = Math.min(widthScale, heightScale);
        this.screenImage.scale.set(scale);
    }
}
